<template><span class="ui-pulse" :class="[`ui-pulse--${tone}`,{'is-animated':animated}]" role="status"><i/><slot>{{ label }}</slot></span></template>
<script setup lang="ts">withDefaults(defineProps<{label?:string;tone?:'success'|'warning'|'danger'|'info';animated?:boolean}>(),{label:'实时',tone:'success',animated:true});</script>
<style scoped>.ui-pulse{display:inline-flex;align-items:center;gap:7px;color:var(--ui-text-muted);font-size:12px}.ui-pulse i{position:relative;width:7px;height:7px;border-radius:50%;background:var(--ui-success)}.ui-pulse.is-animated i:after{position:absolute;inset:-4px;border:1px solid currentColor;border-radius:50%;color:var(--ui-success);content:"";animation:ui-pulse 1.8s ease-out infinite}.ui-pulse--warning i{background:var(--ui-warning)}.ui-pulse--danger i{background:var(--ui-danger)}.ui-pulse--info i{background:var(--ui-info)}@keyframes ui-pulse{0%{opacity:.7;transform:scale(.6)}70%,100%{opacity:0;transform:scale(1.35)}}@media(prefers-reduced-motion:reduce){.ui-pulse.is-animated i:after{animation:none;opacity:.3}}</style>
